-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0001_initial_schema.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — initial schema
--
-- Design notes:
--  * Money is ALWAYS integer cents. No numeric/float columns for money.
--  * Financial state is DERIVED from charges/payments/credits. There is no
--    stored balance column anywhere, by design.
--  * History is preserved: players are archived/soft-deleted, charges are
--    voided rather than removed, and charge amounts are captured at creation
--    so later rate changes never rewrite the past.
--  * Every coach-owned table carries coach_id and is protected by RLS.
--
-- Safe to re-run: every statement is guarded.
-- ============================================================================

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------- enums ----

do $$
begin
  create type session_type as enum ('private', 'group');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type session_status as enum ('scheduled', 'cancelled');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type attendance_status as enum ('unmarked', 'present', 'absent', 'skipped');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type player_level as enum ('Beginner', 'Intermediate', 'Advanced');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type attendance_window as enum ('Same day', '24 hours', '48 hours', '72 hours');
exception when duplicate_object then null;
end $$;

do $$
begin
  create type ui_theme as enum ('Light', 'Dark');
exception when duplicate_object then null;
end $$;

-- --------------------------------------------------------------- coaches ---

create table if not exists coaches (
  id                uuid primary key default gen_random_uuid(),
  auth_user_id      uuid not null unique references auth.users (id) on delete cascade,
  name              text not null default '',
  email             text not null default '',
  business_name     text not null default '',
  default_rate_cents integer not null default 7000 check (default_rate_cents >= 0),
  attendance_window attendance_window not null default '24 hours',
  theme             ui_theme not null default 'Light',
  onboarded_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists coaches_auth_user_id_idx on coaches (auth_user_id);

-- --------------------------------------------------------------- players ---

create table if not exists players (
  id                 uuid primary key default gen_random_uuid(),
  coach_id           uuid not null references coaches (id) on delete cascade,
  name               text not null check (length(btrim(name)) > 0),
  phone              text not null default '',
  email              text not null default '',
  level              player_level not null default 'Beginner',
  -- NULL means "fall back to the coach's default rate".
  default_rate_cents integer check (default_rate_cents is null or default_rate_cents >= 0),
  notes              text not null default '',
  archived           boolean not null default false,
  -- Soft delete: history stays intact and readable.
  deleted_at         timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create index if not exists players_coach_idx on players (coach_id);
create index if not exists players_coach_active_idx on players (coach_id, archived) where deleted_at is null;

-- -------------------------------------------------------------- sessions ---

create table if not exists sessions (
  id                 uuid primary key default gen_random_uuid(),
  coach_id           uuid not null references coaches (id) on delete cascade,
  type               session_type not null,
  name               text not null default '',
  date               date not null,
  -- Minutes from midnight, matching the design's time model.
  start_min          integer not null check (start_min between 0 and 1439),
  duration_min       integer not null check (duration_min between 5 and 480),
  -- Per-player price captured at scheduling time.
  price_cents        integer not null default 0 check (price_cents >= 0),
  is_free            boolean not null default false,
  location           text not null default '',
  capacity           integer check (capacity is null or capacity between 2 and 12),
  status             session_status not null default 'scheduled',
  attendance_skipped boolean not null default false,
  cancelled_at       timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),

  -- A free session must never carry a price.
  constraint sessions_free_has_no_price check (not is_free or price_cents = 0),
  -- Private lessons have no capacity; group sessions must have one.
  constraint sessions_capacity_shape check (
    (type = 'private' and capacity is null) or (type = 'group' and capacity is not null)
  )
);

create index if not exists sessions_coach_date_idx on sessions (coach_id, date);
create index if not exists sessions_coach_status_idx on sessions (coach_id, status);

-- ----------------------------------------------------------- enrollments ---

create table if not exists enrollments (
  id         uuid primary key default gen_random_uuid(),
  coach_id   uuid not null references coaches (id) on delete cascade,
  session_id uuid not null references sessions (id) on delete cascade,
  player_id  uuid not null references players (id) on delete restrict,
  attendance attendance_status not null default 'unmarked',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (session_id, player_id)
);

create index if not exists enrollments_coach_idx on enrollments (coach_id);
create index if not exists enrollments_session_idx on enrollments (session_id);
create index if not exists enrollments_player_idx on enrollments (player_id);

-- --------------------------------------------------------------- charges ---

create table if not exists charges (
  id           uuid primary key default gen_random_uuid(),
  coach_id     uuid not null references coaches (id) on delete cascade,
  player_id    uuid not null references players (id) on delete restrict,
  -- NULL for manual/ad-hoc charges.
  session_id   uuid references sessions (id) on delete restrict,
  amount_cents integer not null check (amount_cents > 0),
  due_date     date not null,
  is_manual    boolean not null default false,
  label        text not null default '',
  note         text not null default '',
  -- Voided charges are written off: they owe nothing but remain on record.
  voided_at    timestamptz,
  void_note    text not null default '',
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index if not exists charges_coach_idx on charges (coach_id);
create index if not exists charges_player_idx on charges (player_id);
create index if not exists charges_session_idx on charges (session_id);
create index if not exists charges_coach_due_idx on charges (coach_id, due_date) where voided_at is null;

-- -------------------------------------------------------------- payments ---
-- Money actually received. Revenue is the sum of these — never of charges.

create table if not exists payments (
  id           uuid primary key default gen_random_uuid(),
  coach_id     uuid not null references coaches (id) on delete cascade,
  charge_id    uuid not null references charges (id) on delete cascade,
  amount_cents integer not null check (amount_cents > 0),
  paid_on      date not null,
  note         text not null default '',
  created_at   timestamptz not null default now()
);

create index if not exists payments_coach_idx on payments (coach_id);
create index if not exists payments_charge_idx on payments (charge_id);
create index if not exists payments_coach_paid_on_idx on payments (coach_id, paid_on);

-- --------------------------------------------------------------- credits ---
-- A reduction of an obligation that is NOT money received.

create table if not exists credits (
  id           uuid primary key default gen_random_uuid(),
  coach_id     uuid not null references coaches (id) on delete cascade,
  charge_id    uuid not null references charges (id) on delete cascade,
  amount_cents integer not null check (amount_cents > 0),
  reason       text not null default '',
  created_at   timestamptz not null default now()
);

create index if not exists credits_coach_idx on credits (coach_id);
create index if not exists credits_charge_idx on credits (charge_id);

-- ------------------------------------------------------- updated_at hook ---

create or replace function set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists coaches_updated_at on coaches;
create trigger coaches_updated_at before update on coaches
  for each row execute function set_updated_at();
drop trigger if exists players_updated_at on players;
create trigger players_updated_at before update on players
  for each row execute function set_updated_at();
drop trigger if exists sessions_updated_at on sessions;
create trigger sessions_updated_at before update on sessions
  for each row execute function set_updated_at();
drop trigger if exists enrollments_updated_at on enrollments;
create trigger enrollments_updated_at before update on enrollments
  for each row execute function set_updated_at();
drop trigger if exists charges_updated_at on charges;
create trigger charges_updated_at before update on charges
  for each row execute function set_updated_at();

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0002_financial_integrity.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — financial integrity
--
-- These constraints are the last line of defence for money. They hold even if
-- the application has a bug, a request is replayed, or two devices submit the
-- same "Mark Paid" at the same moment.
--
-- Safe to re-run: every statement is guarded.
-- ============================================================================

-- Total applied (payments + credits) against one charge, computed inside the
-- database. Used by the guard triggers below.
create or replace function charge_applied_cents(p_charge_id uuid)
returns integer
language sql
stable
as $$
  select
    coalesce((select sum(amount_cents) from payments where charge_id = p_charge_id), 0)
    + coalesce((select sum(amount_cents) from credits  where charge_id = p_charge_id), 0);
$$;

-- Reject any payment/credit that would push a charge past its amount, or that
-- targets a written-off charge. Row locking on the parent charge serialises
-- concurrent inserts, so a double-submitted payment is rejected rather than
-- silently doubling the recorded revenue.
create or replace function guard_charge_application()
returns trigger
language plpgsql
as $$
declare
  v_amount integer;
  v_voided timestamptz;
  v_coach  uuid;
  v_applied integer;
begin
  select amount_cents, voided_at, coach_id
    into v_amount, v_voided, v_coach
    from charges
   where id = new.charge_id
   for update;

  if not found then
    raise exception 'Charge % does not exist', new.charge_id
      using errcode = 'foreign_key_violation';
  end if;

  if v_voided is not null then
    raise exception 'Charge % was written off and cannot be settled', new.charge_id
      using errcode = 'check_violation';
  end if;

  -- Defence in depth: the row must belong to the same coach as its charge.
  if new.coach_id is distinct from v_coach then
    raise exception 'Cross-coach financial write rejected'
      using errcode = 'insufficient_privilege';
  end if;

  v_applied := charge_applied_cents(new.charge_id);

  if v_applied + new.amount_cents > v_amount then
    raise exception
      'Applying % cents would exceed the remaining balance on charge %',
      new.amount_cents, new.charge_id
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

drop trigger if exists payments_guard on payments;
create trigger payments_guard
  before insert or update on payments
  for each row execute function guard_charge_application();

drop trigger if exists credits_guard on credits;
create trigger credits_guard
  before insert or update on credits
  for each row execute function guard_charge_application();

-- A charge may not be voided while money has already been collected against
-- it — that money really was received and must stay in revenue.
create or replace function guard_charge_void()
returns trigger
language plpgsql
as $$
declare
  v_paid integer;
begin
  if new.voided_at is not null and old.voided_at is null then
    select coalesce(sum(amount_cents), 0) into v_paid
      from payments where charge_id = new.id;
    if v_paid > 0 then
      raise exception 'Charge % has payments recorded and cannot be voided', new.id
        using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists charges_void_guard on charges;
create trigger charges_void_guard
  before update on charges
  for each row execute function guard_charge_void();

-- Repricing a charge must never drop it below what has already been applied.
create or replace function guard_charge_amount()
returns trigger
language plpgsql
as $$
declare
  v_applied integer;
begin
  if new.amount_cents is distinct from old.amount_cents then
    v_applied := charge_applied_cents(new.id);
    if new.amount_cents < v_applied then
      raise exception
        'Charge % already has % cents applied; it cannot be repriced to %',
        new.id, v_applied, new.amount_cents
        using errcode = 'check_violation';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists charges_amount_guard on charges;
create trigger charges_amount_guard
  before update on charges
  for each row execute function guard_charge_amount();

-- Enrollments, charges and payments must all belong to the same coach as the
-- parent record they point at. This closes the door on an IDOR that supplied a
-- valid id from another tenant.
create or replace function guard_same_coach()
returns trigger
language plpgsql
as $$
declare
  v_coach uuid;
begin
  if tg_table_name = 'enrollments' then
    select coach_id into v_coach from sessions where id = new.session_id;
    if v_coach is distinct from new.coach_id then
      raise exception 'Session belongs to a different coach'
        using errcode = 'insufficient_privilege';
    end if;
    select coach_id into v_coach from players where id = new.player_id;
    if v_coach is distinct from new.coach_id then
      raise exception 'Player belongs to a different coach'
        using errcode = 'insufficient_privilege';
    end if;

  elsif tg_table_name = 'charges' then
    select coach_id into v_coach from players where id = new.player_id;
    if v_coach is distinct from new.coach_id then
      raise exception 'Player belongs to a different coach'
        using errcode = 'insufficient_privilege';
    end if;
    if new.session_id is not null then
      select coach_id into v_coach from sessions where id = new.session_id;
      if v_coach is distinct from new.coach_id then
        raise exception 'Session belongs to a different coach'
          using errcode = 'insufficient_privilege';
      end if;
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists enrollments_same_coach on enrollments;
create trigger enrollments_same_coach
  before insert or update on enrollments
  for each row execute function guard_same_coach();

drop trigger if exists charges_same_coach on charges;
create trigger charges_same_coach
  before insert or update on charges
  for each row execute function guard_same_coach();

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0003_rls_policies.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — row level security
--
-- Every coach-owned table is readable and writable ONLY by the coach that owns
-- it. Authorization lives here, in the database, not in the frontend and not
-- in the application's query builders. A leaked or guessed row id from another
-- tenant returns nothing.
--
-- Safe to re-run: every statement is guarded.
-- ============================================================================

alter table coaches     enable row level security;
alter table players     enable row level security;
alter table sessions    enable row level security;
alter table enrollments enable row level security;
alter table charges     enable row level security;
alter table payments    enable row level security;
alter table credits     enable row level security;

-- Force RLS even for the table owner, so a misconfigured connection cannot
-- bypass these policies. (The service_role key still bypasses RLS by design;
-- this application never uses it.)
alter table coaches     force row level security;
alter table players     force row level security;
alter table sessions    force row level security;
alter table enrollments force row level security;
alter table charges     force row level security;
alter table payments    force row level security;
alter table credits     force row level security;

-- The coach row belonging to the current authenticated user.
create or replace function current_coach_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select id from coaches where auth_user_id = auth.uid();
$$;

revoke all on function current_coach_id() from public;
grant execute on function current_coach_id() to authenticated;

-- ---------------------------------------------------------------- coaches --

drop policy if exists coaches_select_own on coaches;
create policy coaches_select_own on coaches
  for select using (auth_user_id = auth.uid());

drop policy if exists coaches_insert_own on coaches;
create policy coaches_insert_own on coaches
  for insert with check (auth_user_id = auth.uid());

drop policy if exists coaches_update_own on coaches;
create policy coaches_update_own on coaches
  for update using (auth_user_id = auth.uid())
  with check (auth_user_id = auth.uid());

-- Deleting a coach profile is not an application operation; omit the policy so
-- it is denied by default.

-- ------------------------------------------------- coach-owned data tables --
-- Each table gets the same shape: you may touch a row only when its coach_id
-- resolves to your own coach record.

drop policy if exists players_all_own on players;
create policy players_all_own on players
  for all using (coach_id = current_coach_id())
  with check (coach_id = current_coach_id());

drop policy if exists sessions_all_own on sessions;
create policy sessions_all_own on sessions
  for all using (coach_id = current_coach_id())
  with check (coach_id = current_coach_id());

drop policy if exists enrollments_all_own on enrollments;
create policy enrollments_all_own on enrollments
  for all using (coach_id = current_coach_id())
  with check (coach_id = current_coach_id());

drop policy if exists charges_all_own on charges;
create policy charges_all_own on charges
  for all using (coach_id = current_coach_id())
  with check (coach_id = current_coach_id());

drop policy if exists payments_all_own on payments;
create policy payments_all_own on payments
  for all using (coach_id = current_coach_id())
  with check (coach_id = current_coach_id());

drop policy if exists credits_all_own on credits;
create policy credits_all_own on credits
  for all using (coach_id = current_coach_id())
  with check (coach_id = current_coach_id());

-- Anonymous visitors get nothing at all.
revoke all on all tables in schema public from anon;

grant select, insert, update, delete on
  coaches, players, sessions, enrollments, charges, payments, credits
to authenticated;

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0004_new_coach_bootstrap.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — create a coach profile automatically on signup.
--
-- Without this, the first request after signup has an authenticated user but
-- no coach row, and current_coach_id() returns NULL (which RLS reads as "no
-- access to anything").
--
-- Safe to re-run: every statement is guarded.
-- ============================================================================

create or replace function handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.coaches (auth_user_id, name, email)
  values (
    new.id,
    coalesce(new.raw_user_meta_data ->> 'name', ''),
    coalesce(new.email, '')
  )
  on conflict (auth_user_id) do nothing;
  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_auth_user();

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0005_coach_timezone.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — per-coach timezone
--
-- The application server runs in UTC. Without a per-coach zone, "today",
-- "has this session ended?" and every overdue calculation are wrong for any
-- coach not on UTC — an evening session rolls into tomorrow mid-session.
--
-- Existing rows default to UTC, which is the previous (incorrect but stable)
-- behaviour; coaches set their real zone at onboarding or in Settings.
--
-- Safe to re-run: every statement is guarded.
-- ============================================================================

alter table coaches
  add column if not exists timezone text not null default 'UTC';

comment on column coaches.timezone is
  'IANA timezone name, e.g. America/Los_Angeles. All calendar decisions for this coach are made in this zone.';

-- Cheap sanity guard: an IANA name, not free text. Full validation happens in
-- the application via Intl, which knows the current tz database.
do $$
begin
  alter table coaches
    add constraint coaches_timezone_shape
    check (timezone = 'UTC' or timezone ~ '^[A-Za-z_]+/[A-Za-z0-9_+\-/]+$');
exception
  when duplicate_object then null;
end $$;

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0006_academy_memberships.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — academies and memberships (multi-coach tenancy)
--
-- Until now a `coaches` row was BOTH the business and the one person who ran
-- it, and every data table's `coach_id` was that single tenant key. This
-- migration splits the two concepts:
--
--   academies             the business / tenant (name, default rate, timezone…)
--   academy_memberships   one row per person in an academy, with a role
--                         (renamed from `coaches`; auth_user_id lives here)
--
-- and re-points every data table's tenant column at the academy
-- (`coach_id` -> `academy_id`).
--
-- Existing data is preserved without rewriting a single data row: each
-- existing coach's id is reused as their academy's id, so every `coach_id`
-- value already equals the new `academy_id` value. Every existing coach
-- becomes the owner of their own academy.
--
-- This is deliberately ONE file. The functions, triggers and RLS policies
-- below all refer to the renamed table/column; splitting them across files
-- would leave the database broken if only the first part were applied.
-- ============================================================================

-- ─────────────────────────────────────────────────────────────── academies ──

create type membership_role as enum ('owner', 'coach');

create table academies (
  id                 uuid primary key default gen_random_uuid(),
  business_name      text not null default '',
  -- Fallback rate used when a player has no rate of their own.
  default_rate_cents integer not null default 7000 check (default_rate_cents >= 0),
  attendance_window  attendance_window not null default '24 hours',
  theme              ui_theme not null default 'Light',
  -- IANA name; full validation happens in the application via Intl.
  timezone           text not null default 'UTC'
    constraint academies_timezone_shape
    check (timezone = 'UTC' or timezone ~ '^[A-Za-z_]+/[A-Za-z0-9_+\-/]+$'),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

comment on column academies.timezone is
  'IANA timezone name, e.g. America/Los_Angeles. All calendar decisions for this academy are made in this zone.';

create trigger academies_updated_at before update on academies
  for each row execute function set_updated_at();

-- Reuse each coach's id as their academy's id (see header).
insert into academies
  (id, business_name, default_rate_cents, attendance_window, theme, timezone, created_at)
select
  id, business_name, default_rate_cents, attendance_window, theme, timezone, created_at
from coaches;

-- ─────────────────────────────────────────────── coaches -> memberships ────

alter table coaches add column academy_id uuid;
alter table coaches add column role membership_role;

update coaches set academy_id = id, role = 'owner';

alter table coaches alter column academy_id set not null;
alter table coaches alter column role set not null;
alter table coaches
  add constraint academy_memberships_academy_id_fkey
  foreign key (academy_id) references academies (id) on delete cascade;

-- The business-level columns now live on `academies` only.
alter table coaches
  drop column business_name,
  drop column default_rate_cents,
  drop column attendance_window,
  drop column theme,
  drop column timezone;

alter table coaches rename to academy_memberships;

alter table academy_memberships
  rename constraint coaches_pkey to academy_memberships_pkey;
alter table academy_memberships
  rename constraint coaches_auth_user_id_key to academy_memberships_auth_user_id_key;
alter index coaches_auth_user_id_idx rename to academy_memberships_auth_user_id_idx;
alter trigger coaches_updated_at on academy_memberships
  rename to academy_memberships_updated_at;

create index academy_memberships_academy_idx on academy_memberships (academy_id);

-- ─────────────────────────────── re-point every data table at the academy ──
-- The values are unchanged (academy id == old coach id), so this is DDL only.

alter table players     rename column coach_id to academy_id;
alter table sessions    rename column coach_id to academy_id;
alter table enrollments rename column coach_id to academy_id;
alter table charges     rename column coach_id to academy_id;
alter table payments    rename column coach_id to academy_id;
alter table credits     rename column coach_id to academy_id;

alter table players     drop constraint players_coach_id_fkey;
alter table sessions    drop constraint sessions_coach_id_fkey;
alter table enrollments drop constraint enrollments_coach_id_fkey;
alter table charges     drop constraint charges_coach_id_fkey;
alter table payments    drop constraint payments_coach_id_fkey;
alter table credits     drop constraint credits_coach_id_fkey;

alter table players     add constraint players_academy_id_fkey
  foreign key (academy_id) references academies (id) on delete cascade;
alter table sessions    add constraint sessions_academy_id_fkey
  foreign key (academy_id) references academies (id) on delete cascade;
alter table enrollments add constraint enrollments_academy_id_fkey
  foreign key (academy_id) references academies (id) on delete cascade;
alter table charges     add constraint charges_academy_id_fkey
  foreign key (academy_id) references academies (id) on delete cascade;
alter table payments    add constraint payments_academy_id_fkey
  foreign key (academy_id) references academies (id) on delete cascade;
alter table credits     add constraint credits_academy_id_fkey
  foreign key (academy_id) references academies (id) on delete cascade;

alter index players_coach_idx          rename to players_academy_idx;
alter index players_coach_active_idx   rename to players_academy_active_idx;
alter index sessions_coach_date_idx    rename to sessions_academy_date_idx;
alter index sessions_coach_status_idx  rename to sessions_academy_status_idx;
alter index enrollments_coach_idx      rename to enrollments_academy_idx;
alter index charges_coach_idx          rename to charges_academy_idx;
alter index charges_coach_due_idx      rename to charges_academy_due_idx;
alter index payments_coach_idx         rename to payments_academy_idx;
alter index payments_coach_paid_on_idx rename to payments_academy_paid_on_idx;
alter index credits_coach_idx          rename to credits_academy_idx;

-- ───────────────────────────────── retire the coach-keyed policies/guards ──

drop policy players_all_own     on players;
drop policy sessions_all_own    on sessions;
drop policy enrollments_all_own on enrollments;
drop policy charges_all_own     on charges;
drop policy payments_all_own    on payments;
drop policy credits_all_own     on credits;
drop policy coaches_select_own  on academy_memberships;
drop policy coaches_insert_own  on academy_memberships;
drop policy coaches_update_own  on academy_memberships;

drop function current_coach_id();

drop trigger enrollments_same_coach on enrollments;
drop trigger charges_same_coach     on charges;
drop function guard_same_coach();

-- ─────────────────────────────────────────────────── identity helpers ──────

-- The academy the current authenticated user belongs to.
create or replace function current_academy_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select academy_id from academy_memberships where auth_user_id = auth.uid();
$$;

-- The current user's role within that academy.
create or replace function current_membership_role()
returns membership_role
language sql
stable
security definer
set search_path = public
as $$
  select role from academy_memberships where auth_user_id = auth.uid();
$$;

revoke all on function current_academy_id()      from public;
revoke all on function current_membership_role() from public;
grant execute on function current_academy_id()      to authenticated;
grant execute on function current_membership_role() to authenticated;

-- ────────────────────────────────────────────── integrity guards (renamed) ──
-- Same invariants as 0002, keyed on academy_id instead of coach_id.

create or replace function guard_charge_application()
returns trigger
language plpgsql
as $$
declare
  v_amount integer;
  v_voided timestamptz;
  v_academy uuid;
  v_applied integer;
begin
  select amount_cents, voided_at, academy_id
    into v_amount, v_voided, v_academy
    from charges
   where id = new.charge_id
   for update;

  if not found then
    raise exception 'Charge % does not exist', new.charge_id
      using errcode = 'foreign_key_violation';
  end if;

  if v_voided is not null then
    raise exception 'Charge % was written off and cannot be settled', new.charge_id
      using errcode = 'check_violation';
  end if;

  -- Defence in depth: the row must belong to the same academy as its charge.
  if new.academy_id is distinct from v_academy then
    raise exception 'Cross-academy financial write rejected'
      using errcode = 'insufficient_privilege';
  end if;

  v_applied := charge_applied_cents(new.charge_id);

  if v_applied + new.amount_cents > v_amount then
    raise exception
      'Applying % cents would exceed the remaining balance on charge %',
      new.amount_cents, new.charge_id
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

create or replace function guard_same_academy()
returns trigger
language plpgsql
as $$
declare
  v_academy uuid;
begin
  if tg_table_name = 'enrollments' then
    select academy_id into v_academy from sessions where id = new.session_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Session belongs to a different academy'
        using errcode = 'insufficient_privilege';
    end if;
    select academy_id into v_academy from players where id = new.player_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Player belongs to a different academy'
        using errcode = 'insufficient_privilege';
    end if;

  elsif tg_table_name = 'charges' then
    select academy_id into v_academy from players where id = new.player_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Player belongs to a different academy'
        using errcode = 'insufficient_privilege';
    end if;
    if new.session_id is not null then
      select academy_id into v_academy from sessions where id = new.session_id;
      if v_academy is distinct from new.academy_id then
        raise exception 'Session belongs to a different academy'
          using errcode = 'insufficient_privilege';
      end if;
    end if;
  end if;

  return new;
end;
$$;

create trigger enrollments_same_academy
  before insert or update on enrollments
  for each row execute function guard_same_academy();

create trigger charges_same_academy
  before insert or update on charges
  for each row execute function guard_same_academy();

-- A membership's role, academy and identity are set once, at creation. There is
-- no application path that changes them, so refuse every attempt — this is what
-- stops a coach promoting themselves to owner with a raw UPDATE.
create or replace function guard_membership_immutable()
returns trigger
language plpgsql
as $$
begin
  if new.role is distinct from old.role
     or new.academy_id is distinct from old.academy_id
     or new.auth_user_id is distinct from old.auth_user_id then
    raise exception 'A membership''s role, academy and user cannot be changed'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger academy_memberships_immutable
  before update on academy_memberships
  for each row execute function guard_membership_immutable();

-- ───────────────────────────────────────────────────────────────── RLS ─────

alter table academies           enable row level security;
alter table academy_memberships enable row level security;
alter table academies           force row level security;
alter table academy_memberships force row level security;

-- academies: every member can read their academy; only the owner can change it.
-- There is no INSERT/DELETE policy: academies are created only by the signup
-- trigger / bootstrap RPC below, and are never deleted through the API.
create policy academies_select_member on academies
  for select using (id = current_academy_id());

create policy academies_update_owner on academies
  for update using (id = current_academy_id() and current_membership_role() = 'owner')
  with check (id = current_academy_id() and current_membership_role() = 'owner');

-- academy_memberships: members see their whole team; each member edits only
-- their own row (name/email/onboarding — the immutability trigger above blocks
-- role/academy/user changes). No INSERT/DELETE policy yet: rows are created by
-- the signup trigger / bootstrap RPC.
create policy memberships_select_team on academy_memberships
  for select using (academy_id = current_academy_id());

create policy memberships_update_self on academy_memberships
  for update using (auth_user_id = auth.uid())
  with check (auth_user_id = auth.uid());

-- Shared, academy-scoped data: every member can read and write.
create policy players_all_member on players
  for all using (academy_id = current_academy_id())
  with check (academy_id = current_academy_id());

create policy sessions_all_member on sessions
  for all using (academy_id = current_academy_id())
  with check (academy_id = current_academy_id());

create policy enrollments_all_member on enrollments
  for all using (academy_id = current_academy_id())
  with check (academy_id = current_academy_id());

-- Charges are financial history, not ordinary shared data. Every member can
-- READ them (paid/unpaid status shows on lesson and player screens), but a
-- coach's write access is limited to what their session workflows imply:
--   * INSERT  the charge a real booking creates (session-linked, non-manual,
--             the player enrolled, the session still scheduled)
--   * UPDATE  move an unsettled charge's due date with its session, or write it
--             off when that session is cancelled
-- Everything else — manual charges, changing an amount or note, crediting,
-- recording payments, writing off outside a cancellation — is owner-only. The
-- guard triggers below narrow the coach's UPDATE; there is NO delete policy
-- for anyone: charges are voided, never removed.
create policy charges_select_member on charges
  for select using (academy_id = current_academy_id());

create policy charges_insert_owner on charges
  for insert with check (
    academy_id = current_academy_id() and current_membership_role() = 'owner'
  );

create policy charges_insert_workflow on charges
  for insert with check (
    academy_id = current_academy_id()
    and session_id is not null
    and is_manual = false
    and voided_at is null
  );

create policy charges_update_member on charges
  for update using (academy_id = current_academy_id())
  with check (academy_id = current_academy_id());

-- Who is acting? NULL means there is no end-user context at all (a migration,
-- the seed script, a server-side job) and is treated as trusted; every
-- end-user request has a JWT and therefore a role.

create or replace function guard_charge_insert()
returns trigger
language plpgsql
as $$
declare
  v_role   membership_role := current_membership_role();
  v_status session_status;
begin
  if v_role is null or v_role = 'owner' then
    return new;
  end if;

  if new.is_manual or new.session_id is null then
    raise exception 'Only the academy owner can create a manual charge'
      using errcode = 'insufficient_privilege';
  end if;

  select status into v_status from sessions where id = new.session_id;
  if v_status is distinct from 'scheduled' then
    raise exception 'A charge can only be created for a scheduled session'
      using errcode = 'insufficient_privilege';
  end if;

  if not exists (
    select 1 from enrollments
     where session_id = new.session_id and player_id = new.player_id
  ) then
    raise exception 'A charge can only be created for a player enrolled in the session'
      using errcode = 'insufficient_privilege';
  end if;

  return new;
end;
$$;

create trigger charges_insert_guard
  before insert on charges
  for each row execute function guard_charge_insert();

create or replace function guard_charge_update()
returns trigger
language plpgsql
as $$
declare
  v_role   membership_role := current_membership_role();
  v_status session_status;
begin
  -- A charge's identity and origin never change, for anyone.
  if new.academy_id is distinct from old.academy_id
     or new.player_id is distinct from old.player_id
     or new.session_id is distinct from old.session_id
     or new.is_manual is distinct from old.is_manual
     or new.created_at is distinct from old.created_at then
    raise exception 'A charge''s academy, player, session and origin cannot be changed'
      using errcode = 'insufficient_privilege';
  end if;

  if v_role is null or v_role = 'owner' then
    return new;
  end if;

  -- A coach may not change what a charge says or is worth.
  if new.amount_cents is distinct from old.amount_cents
     or new.label is distinct from old.label
     or new.note is distinct from old.note then
    raise exception 'Only the academy owner can change the amount or details of a charge'
      using errcode = 'insufficient_privilege';
  end if;

  -- Settled or already-written-off charges are the owner's to touch.
  if old.voided_at is not null or charge_applied_cents(old.id) > 0 then
    raise exception 'Only the academy owner can change a settled or written-off charge'
      using errcode = 'insufficient_privilege';
  end if;

  -- The one write-off a coach may make: as the direct result of cancelling the
  -- charge's own session. Never un-void, never void for any other reason.
  if new.voided_at is distinct from old.voided_at
     or new.void_note is distinct from old.void_note then
    if new.voided_at is null then
      raise exception 'Only the academy owner can reinstate a written-off charge'
        using errcode = 'insufficient_privilege';
    end if;
    select status into v_status from sessions where id = new.session_id;
    if new.session_id is null or v_status is distinct from 'cancelled' then
      raise exception 'A coach can only write off a charge by cancelling its session'
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  return new;
end;
$$;

create trigger charges_update_guard
  before update on charges
  for each row execute function guard_charge_update();

-- Money RECEIVED (payments) and reductions of what is owed (credits) are
-- owner-only to write. Members can still read them: a charge's paid/unpaid
-- status is derived from these rows and shows on lesson and player screens.
create policy payments_select_member on payments
  for select using (academy_id = current_academy_id());
create policy payments_write_owner on payments
  for all using (academy_id = current_academy_id() and current_membership_role() = 'owner')
  with check (academy_id = current_academy_id() and current_membership_role() = 'owner');

create policy credits_select_member on credits
  for select using (academy_id = current_academy_id());
create policy credits_write_owner on credits
  for all using (academy_id = current_academy_id() and current_membership_role() = 'owner')
  with check (academy_id = current_academy_id() and current_membership_role() = 'owner');

-- ─────────────────────────────────────────────────────────── grants ────────

revoke all on academies, academy_memberships from anon;
revoke all on academies, academy_memberships from authenticated;
grant select, update on academies, academy_memberships to authenticated;

-- Financial history is voided, never deleted (see the charges policies above).
revoke delete on charges from authenticated;

-- ─────────────────────────────────────────────────── signup bootstrap ──────

-- On signup, create a new academy with the new user as its owner.
create or replace function handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_academy uuid;
begin
  if exists (select 1 from academy_memberships where auth_user_id = new.id) then
    return new;
  end if;

  insert into academies default values returning id into v_academy;

  insert into academy_memberships (academy_id, auth_user_id, role, name, email)
  values (
    v_academy,
    new.id,
    'owner',
    coalesce(new.raw_user_meta_data ->> 'name', ''),
    coalesce(new.email, '')
  );
  return new;
end;
$$;

-- Application fallback for a signed-in user who somehow has no membership (the
-- trigger normally makes one). A security-definer RPC rather than an INSERT
-- policy, so no client can ever create academies or memberships directly.
-- Idempotent: returns the existing membership id when there already is one.
create or replace function bootstrap_academy_owner(p_name text, p_email text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_academy uuid;
  v_membership uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = 'insufficient_privilege';
  end if;

  select id into v_membership from academy_memberships where auth_user_id = auth.uid();
  if found then
    return v_membership;
  end if;

  insert into academies default values returning id into v_academy;

  insert into academy_memberships (academy_id, auth_user_id, role, name, email)
  values (v_academy, auth.uid(), 'owner', coalesce(p_name, ''), coalesce(p_email, ''))
  returning id into v_membership;

  return v_membership;
end;
$$;

revoke all on function bootstrap_academy_owner(text, text) from public;
grant execute on function bootstrap_academy_owner(text, text) to authenticated;

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0007_charge_price_snapshots.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — charges are historical price snapshots
--
-- A charge records what was AGREED at the moment it was created. It must never
-- be re-derived from a live price: changing a player's rate, the academy's
-- default rate, a session's price or (later) a program's price options must
-- never change a charge that already exists.
--
-- `amount_cents` was already captured at creation. This migration adds the
-- provenance that makes the snapshot self-explanatory and auditable, without
-- pointing at any live row:
--
--   price_source          where the amount came from
--   price_basis           what the amount is per (session, week, month…)
--   standard_amount_cents what the standard price was at that moment, so a
--                         discount or premium is visible: amount != standard
--
-- Deliberately NO foreign key to a price/option row: those rows may be edited
-- or archived later, and the charge must stay exactly as it was.
--
-- Programs (a later migration) add their own price options and per-participant
-- agreements; a program charge snapshots the participant's AGREED price into
-- these same columns.
-- ============================================================================

create type price_source as enum (
  'academy_default',  -- the academy's default rate
  'player_default',   -- the player's own default rate
  'session_price',    -- the price set on the session/booking itself
  'program_option',   -- a program's standard price option
  'custom',           -- deliberately differs from the standard for this booking
  'manual'            -- an ad-hoc charge entered by the owner
);

create type price_basis as enum (
  'per_session', 'drop_in', 'weekly', 'monthly', 'full_program', 'custom'
);

alter table charges
  add column price_source price_source,
  add column price_basis price_basis,
  add column standard_amount_cents integer
    check (standard_amount_cents is null or standard_amount_cents >= 0);

-- Existing charges: the honest description of where their amount came from.
-- A session-linked charge took its amount from the session's price; whether
-- that equalled a default at the time is unknowable now, so it is not claimed.
update charges
   set price_source = case when is_manual then 'manual' else 'session_price' end::price_source,
       price_basis  = case when is_manual then null else 'per_session' end::price_basis;

alter table charges alter column price_source set not null;

-- Manual charges are exactly the ones whose source is 'manual'.
alter table charges
  add constraint charges_source_matches_origin
  check ((is_manual and price_source = 'manual') or (not is_manual and price_source <> 'manual'));

comment on column charges.standard_amount_cents is
  'The standard price at the moment the charge was created. NULL when there was no standard (manual charges, per-session group prices).';

-- ─────────────────────────────────────────── snapshots are immutable ───────
-- Extends the update guard from 0006: the snapshot columns never change. The
-- single sanctioned exception is an owner repricing an unpaid charge, which
-- must relabel its source as 'custom' so the record stays truthful (the
-- amount no longer equals the standard, and standard_amount_cents shows it).

create or replace function guard_charge_update()
returns trigger
language plpgsql
as $$
declare
  v_role   membership_role := current_membership_role();
  v_status session_status;
begin
  -- A charge's identity and origin never change, for anyone.
  if new.academy_id is distinct from old.academy_id
     or new.player_id is distinct from old.player_id
     or new.session_id is distinct from old.session_id
     or new.is_manual is distinct from old.is_manual
     or new.created_at is distinct from old.created_at then
    raise exception 'A charge''s academy, player, session and origin cannot be changed'
      using errcode = 'insufficient_privilege';
  end if;

  -- Neither does its price snapshot.
  if new.price_basis is distinct from old.price_basis
     or new.standard_amount_cents is distinct from old.standard_amount_cents then
    raise exception 'A charge''s price snapshot cannot be changed'
      using errcode = 'insufficient_privilege';
  end if;

  if new.price_source is distinct from old.price_source
     and not (new.price_source = 'custom' and new.amount_cents is distinct from old.amount_cents) then
    raise exception 'A charge''s price source can only change to custom when it is repriced'
      using errcode = 'insufficient_privilege';
  end if;

  -- The record must stay truthful: an amount that no longer matches its
  -- original basis is 'custom'. (Manual charges have no standard to depart from
  -- and stay 'manual'.)
  if new.amount_cents is distinct from old.amount_cents
     and not new.is_manual
     and new.price_source <> 'custom' then
    raise exception 'A repriced charge must be marked custom'
      using errcode = 'check_violation';
  end if;

  if v_role is null or v_role = 'owner' then
    return new;
  end if;

  -- A coach may not change what a charge says or is worth.
  if new.amount_cents is distinct from old.amount_cents
     or new.label is distinct from old.label
     or new.note is distinct from old.note then
    raise exception 'Only the academy owner can change the amount or details of a charge'
      using errcode = 'insufficient_privilege';
  end if;

  -- Settled or already-written-off charges are the owner's to touch.
  if old.voided_at is not null or charge_applied_cents(old.id) > 0 then
    raise exception 'Only the academy owner can change a settled or written-off charge'
      using errcode = 'insufficient_privilege';
  end if;

  -- The one write-off a coach may make: as the direct result of cancelling the
  -- charge's own session. Never un-void, never void for any other reason.
  if new.voided_at is distinct from old.voided_at
     or new.void_note is distinct from old.void_note then
    if new.voided_at is null then
      raise exception 'Only the academy owner can reinstate a written-off charge'
        using errcode = 'insufficient_privilege';
    end if;
    select status into v_status from sessions where id = new.session_id;
    if new.session_id is null or v_status is distinct from 'cancelled' then
      raise exception 'A coach can only write off a charge by cancelling its session'
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  return new;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0008_programs.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — programs (recurring clinics/camps) and their pricing
--
--   programs               a recurring group offering. NO price column: a
--                          program has price OPTIONS, not one price.
--   program_price_options  e.g. "Weekly $150", "Drop-in $35". Editing or
--                          archiving one never touches an existing agreement
--                          or charge — those hold snapshots.
--   program_enrollments    the roster, and each participant's AGREEMENT: the
--                          price they agreed to, snapshotted from an option
--                          (or a deliberate custom amount, owner only).
--
-- Charges for a program participant copy the AGREED amount, basis and
-- standard into the same snapshot columns added in 0007. The database checks
-- that a program-linked charge equals its enrollment's agreement, so nobody —
-- including a coach — can invent a different amount at charge time.
--
-- Sessions gain program_id (a program's generated occurrences); session
-- enrollments gain `expected` (the planning list, distinct from attendance).
-- ============================================================================

create type program_audience   as enum ('youth', 'adult');
create type program_status     as enum ('active', 'ended');
create type roster_status      as enum ('active', 'ended');
create type agreement_source   as enum ('program_option', 'custom');

-- ─────────────────────────────────────────────────────────────── programs ──

create table programs (
  id            uuid primary key default gen_random_uuid(),
  academy_id    uuid not null references academies (id) on delete cascade,
  name          text not null check (length(btrim(name)) > 0),
  audience      program_audience not null default 'youth',
  -- 0 = Sunday … 6 = Saturday
  weekdays      smallint[] not null
    check (cardinality(weekdays) > 0 and weekdays <@ array[0,1,2,3,4,5,6]::smallint[]),
  start_min     integer not null check (start_min between 0 and 1439),
  duration_min  integer not null check (duration_min between 5 and 480),
  location      text not null default '',
  capacity      integer check (capacity is null or capacity >= 2),
  age_range     text not null default '',
  starts_on     date not null,
  ends_on       date,
  status        program_status not null default 'active',
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint programs_dates_ordered check (ends_on is null or ends_on >= starts_on)
);

create index programs_academy_idx on programs (academy_id);

create trigger programs_updated_at before update on programs
  for each row execute function set_updated_at();

-- ───────────────────────────────────────────────────────── price options ────

create table program_price_options (
  id            uuid primary key default gen_random_uuid(),
  academy_id    uuid not null references academies (id) on delete cascade,
  program_id    uuid not null references programs (id) on delete cascade,
  label         text not null check (length(btrim(label)) > 0),
  basis         price_basis not null,
  amount_cents  integer not null check (amount_cents >= 0),
  position      integer not null default 0,
  -- Options are archived, not deleted, so agreements can still name them.
  archived_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index program_price_options_program_idx on program_price_options (program_id);

create trigger program_price_options_updated_at before update on program_price_options
  for each row execute function set_updated_at();

-- ───────────────────────────────────────────────── roster + agreements ─────

create table program_enrollments (
  id                    uuid primary key default gen_random_uuid(),
  academy_id            uuid not null references academies (id) on delete cascade,
  program_id            uuid not null references programs (id) on delete restrict,
  player_id             uuid not null references players (id) on delete restrict,
  status                roster_status not null default 'active',
  joined_on             date not null,
  ended_on              date,

  -- The agreement, snapshotted when it was made. price_option_id is a soft
  -- pointer for context only; the agreed_* values are the truth.
  price_option_id       uuid references program_price_options (id) on delete set null,
  agreed_label          text not null,
  agreed_basis          price_basis not null,
  agreed_amount_cents   integer not null check (agreed_amount_cents >= 0),
  standard_amount_cents integer check (standard_amount_cents is null or standard_amount_cents >= 0),
  agreement_source      agreement_source not null,
  agreement_note        text not null default '',

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);

create unique index program_enrollments_one_active
  on program_enrollments (program_id, player_id) where status = 'active';
create index program_enrollments_academy_idx on program_enrollments (academy_id);
create index program_enrollments_player_idx  on program_enrollments (player_id);

create trigger program_enrollments_updated_at before update on program_enrollments
  for each row execute function set_updated_at();

-- ───────────────────────────────── sessions, session enrollments, charges ──

alter table sessions
  add column program_id uuid references programs (id) on delete restrict;
create index sessions_program_idx on sessions (program_id) where program_id is not null;

-- A program's occurrences can have a large roster and no per-session capacity.
alter table sessions drop constraint sessions_capacity_shape;
alter table sessions drop constraint sessions_capacity_check;
alter table sessions
  add constraint sessions_capacity_min check (capacity is null or capacity >= 2),
  add constraint sessions_capacity_cap
    check (program_id is not null or capacity is null or capacity <= 12),
  add constraint sessions_capacity_shape check (
    (type = 'private' and capacity is null and program_id is null)
    or (type = 'group' and (capacity is not null or program_id is not null))
  );

-- The planning list for an occurrence, separate from actual attendance.
alter table enrollments add column expected boolean not null default true;

alter table charges
  add column program_id            uuid references programs (id) on delete restrict,
  add column program_enrollment_id uuid references program_enrollments (id) on delete restrict,
  add column period_start          date,
  add column period_end            date,
  add constraint charges_program_coherent
    check ((program_id is null) = (program_enrollment_id is null)),
  add constraint charges_period_ordered
    check (period_end is null or (period_start is not null and period_end >= period_start));

create index charges_program_enrollment_idx on charges (program_enrollment_id)
  where program_enrollment_id is not null;

-- ─────────────────────────────────────────────── same-academy invariants ────

create or replace function guard_same_academy()
returns trigger
language plpgsql
as $$
declare
  v_academy uuid;
begin
  if tg_table_name = 'enrollments' then
    select academy_id into v_academy from sessions where id = new.session_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Session belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;
    select academy_id into v_academy from players where id = new.player_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Player belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;

  elsif tg_table_name = 'charges' then
    select academy_id into v_academy from players where id = new.player_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Player belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;
    if new.session_id is not null then
      select academy_id into v_academy from sessions where id = new.session_id;
      if v_academy is distinct from new.academy_id then
        raise exception 'Session belongs to a different academy' using errcode = 'insufficient_privilege';
      end if;
    end if;
    if new.program_id is not null then
      select academy_id into v_academy from programs where id = new.program_id;
      if v_academy is distinct from new.academy_id then
        raise exception 'Program belongs to a different academy' using errcode = 'insufficient_privilege';
      end if;
    end if;

  elsif tg_table_name = 'program_enrollments' then
    select academy_id into v_academy from programs where id = new.program_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Program belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;
    select academy_id into v_academy from players where id = new.player_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Player belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;

  elsif tg_table_name = 'program_price_options' then
    select academy_id into v_academy from programs where id = new.program_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Program belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;

  elsif tg_table_name = 'sessions' then
    if new.program_id is not null then
      select academy_id into v_academy from programs where id = new.program_id;
      if v_academy is distinct from new.academy_id then
        raise exception 'Program belongs to a different academy' using errcode = 'insufficient_privilege';
      end if;
    end if;
  end if;

  return new;
end;
$$;

create trigger program_enrollments_same_academy
  before insert or update on program_enrollments
  for each row execute function guard_same_academy();
create trigger program_price_options_same_academy
  before insert or update on program_price_options
  for each row execute function guard_same_academy();
create trigger sessions_same_academy
  before insert or update on sessions
  for each row execute function guard_same_academy();

-- ───────────────────────────────────── agreements: what may be written ─────

-- An agreement made from a price option must MATCH that option at that moment
-- (for any role). A custom agreement is a deliberate departure from the
-- standard and belongs to the owner.
create or replace function guard_program_enrollment_insert()
returns trigger
language plpgsql
as $$
declare
  v_role membership_role := current_membership_role();
  v_opt  program_price_options%rowtype;
begin
  if new.agreement_source = 'program_option' then
    select * into v_opt from program_price_options where id = new.price_option_id;
    if not found
       or v_opt.program_id is distinct from new.program_id
       or v_opt.archived_at is not null then
      raise exception 'Choose one of the program''s current price options'
        using errcode = 'check_violation';
    end if;
    if new.agreed_amount_cents is distinct from v_opt.amount_cents
       or new.agreed_basis is distinct from v_opt.basis
       or new.agreed_label is distinct from v_opt.label
       or new.standard_amount_cents is distinct from v_opt.amount_cents then
      raise exception 'The agreement must match the price option it was made from'
        using errcode = 'check_violation';
    end if;
  elsif v_role is not null and v_role <> 'owner' then
    raise exception 'Only the academy owner can agree a custom price'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger program_enrollments_insert_guard
  before insert on program_enrollments
  for each row execute function guard_program_enrollment_insert();

-- Roster identity never changes. A coach may end a participant's place; only
-- the owner may change the agreement, and only going forward (existing charges
-- are snapshots and are untouched).
create or replace function guard_program_enrollment_update()
returns trigger
language plpgsql
as $$
declare
  v_role membership_role := current_membership_role();
begin
  if new.academy_id is distinct from old.academy_id
     or new.program_id is distinct from old.program_id
     or new.player_id  is distinct from old.player_id
     or new.joined_on  is distinct from old.joined_on
     or new.created_at is distinct from old.created_at then
    raise exception 'A roster place''s program, player and start date cannot be changed'
      using errcode = 'insufficient_privilege';
  end if;

  if v_role is null or v_role = 'owner' then
    return new;
  end if;

  if new.price_option_id       is distinct from old.price_option_id
     or new.agreed_label        is distinct from old.agreed_label
     or new.agreed_basis        is distinct from old.agreed_basis
     or new.agreed_amount_cents is distinct from old.agreed_amount_cents
     or new.standard_amount_cents is distinct from old.standard_amount_cents
     or new.agreement_source    is distinct from old.agreement_source
     or new.agreement_note      is distinct from old.agreement_note then
    raise exception 'Only the academy owner can change an agreed price'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger program_enrollments_update_guard
  before update on program_enrollments
  for each row execute function guard_program_enrollment_update();

-- ───────────────────────────────────── charges: program-linked snapshots ────

create or replace function guard_charge_insert()
returns trigger
language plpgsql
as $$
declare
  v_role   membership_role := current_membership_role();
  v_status session_status;
  v_sess_program uuid;
  v_enr    program_enrollments%rowtype;
begin
  -- A program charge must be exactly what its enrollment's agreement says, for
  -- everyone: there is no way to charge a program participant a different
  -- amount than they agreed.
  if new.program_enrollment_id is not null then
    select * into v_enr from program_enrollments where id = new.program_enrollment_id;
    if not found
       or v_enr.academy_id is distinct from new.academy_id
       or v_enr.program_id is distinct from new.program_id
       or v_enr.player_id  is distinct from new.player_id then
      raise exception 'A program charge must match its enrollment'
        using errcode = 'check_violation';
    end if;
    if v_enr.status <> 'active' then
      raise exception 'That program place has ended'
        using errcode = 'check_violation';
    end if;
    if new.amount_cents is distinct from v_enr.agreed_amount_cents
       or new.price_basis is distinct from v_enr.agreed_basis
       or new.standard_amount_cents is distinct from v_enr.standard_amount_cents
       or new.price_source is distinct from
            (case when v_enr.agreement_source = 'program_option'
                  then 'program_option' else 'custom' end)::price_source then
      raise exception 'A program charge must equal the participant''s agreed price'
        using errcode = 'check_violation';
    end if;
  end if;

  if v_role is null or v_role = 'owner' then
    return new;
  end if;

  if new.is_manual or (new.session_id is null and new.program_enrollment_id is null) then
    raise exception 'Only the academy owner can create a manual charge'
      using errcode = 'insufficient_privilege';
  end if;

  if new.session_id is not null then
    select status, program_id into v_status, v_sess_program
      from sessions where id = new.session_id;
    if v_status is distinct from 'scheduled' then
      raise exception 'A charge can only be created for a scheduled session'
        using errcode = 'insufficient_privilege';
    end if;
    if not exists (
      select 1 from enrollments
       where session_id = new.session_id and player_id = new.player_id
    ) then
      raise exception 'A charge can only be created for a player enrolled in the session'
        using errcode = 'insufficient_privilege';
    end if;
    -- A program occurrence is charged only through a program agreement.
    if v_sess_program is not null and new.program_enrollment_id is null then
      raise exception 'A program session can only be charged through a program enrollment'
        using errcode = 'insufficient_privilege';
    end if;
    if v_sess_program is distinct from new.program_id then
      raise exception 'The charge''s program must match its session''s program'
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end;
$$;

-- Program identity, like the rest of a charge's provenance, never changes.
create or replace function guard_charge_update()
returns trigger
language plpgsql
as $$
declare
  v_role   membership_role := current_membership_role();
  v_status session_status;
begin
  if new.academy_id is distinct from old.academy_id
     or new.player_id is distinct from old.player_id
     or new.session_id is distinct from old.session_id
     or new.is_manual is distinct from old.is_manual
     or new.program_id is distinct from old.program_id
     or new.program_enrollment_id is distinct from old.program_enrollment_id
     or new.period_start is distinct from old.period_start
     or new.period_end is distinct from old.period_end
     or new.created_at is distinct from old.created_at then
    raise exception 'A charge''s academy, player, session, program and origin cannot be changed'
      using errcode = 'insufficient_privilege';
  end if;

  if new.price_basis is distinct from old.price_basis
     or new.standard_amount_cents is distinct from old.standard_amount_cents then
    raise exception 'A charge''s price snapshot cannot be changed'
      using errcode = 'insufficient_privilege';
  end if;

  if new.price_source is distinct from old.price_source
     and not (new.price_source = 'custom' and new.amount_cents is distinct from old.amount_cents) then
    raise exception 'A charge''s price source can only change to custom when it is repriced'
      using errcode = 'insufficient_privilege';
  end if;

  if new.amount_cents is distinct from old.amount_cents
     and not new.is_manual
     and new.price_source <> 'custom' then
    raise exception 'A repriced charge must be marked custom'
      using errcode = 'check_violation';
  end if;

  if v_role is null or v_role = 'owner' then
    return new;
  end if;

  if new.amount_cents is distinct from old.amount_cents
     or new.label is distinct from old.label
     or new.note is distinct from old.note then
    raise exception 'Only the academy owner can change the amount or details of a charge'
      using errcode = 'insufficient_privilege';
  end if;

  if old.voided_at is not null or charge_applied_cents(old.id) > 0 then
    raise exception 'Only the academy owner can change a settled or written-off charge'
      using errcode = 'insufficient_privilege';
  end if;

  if new.voided_at is distinct from old.voided_at
     or new.void_note is distinct from old.void_note then
    if new.voided_at is null then
      raise exception 'Only the academy owner can reinstate a written-off charge'
        using errcode = 'insufficient_privilege';
    end if;
    select status into v_status from sessions where id = new.session_id;
    if new.session_id is null or v_status is distinct from 'cancelled' then
      raise exception 'A coach can only write off a charge by cancelling its session'
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  return new;
end;
$$;

-- Members may insert the charge a booking OR a program enrollment implies.
drop policy charges_insert_workflow on charges;
create policy charges_insert_workflow on charges
  for insert with check (
    academy_id = current_academy_id()
    and (session_id is not null or program_enrollment_id is not null)
    and is_manual = false
    and voided_at is null
  );

-- ───────────────────────────────────────────────────────────────── RLS ─────

alter table programs              enable row level security;
alter table program_price_options enable row level security;
alter table program_enrollments   enable row level security;
alter table programs              force row level security;
alter table program_price_options force row level security;
alter table program_enrollments   force row level security;

-- Programs and their price options are the owner's to define; everyone reads.
create policy programs_select_member on programs
  for select using (academy_id = current_academy_id());
create policy programs_insert_owner on programs
  for insert with check (academy_id = current_academy_id() and current_membership_role() = 'owner');
create policy programs_update_owner on programs
  for update using (academy_id = current_academy_id() and current_membership_role() = 'owner')
  with check (academy_id = current_academy_id() and current_membership_role() = 'owner');

create policy program_price_options_select_member on program_price_options
  for select using (academy_id = current_academy_id());
create policy program_price_options_insert_owner on program_price_options
  for insert with check (academy_id = current_academy_id() and current_membership_role() = 'owner');
create policy program_price_options_update_owner on program_price_options
  for update using (academy_id = current_academy_id() and current_membership_role() = 'owner')
  with check (academy_id = current_academy_id() and current_membership_role() = 'owner');

-- The roster is a coach workflow (the triggers above narrow what a coach may
-- write). No delete for anyone: a place is ended, its history stays.
create policy program_enrollments_select_member on program_enrollments
  for select using (academy_id = current_academy_id());
create policy program_enrollments_insert_member on program_enrollments
  for insert with check (academy_id = current_academy_id());
create policy program_enrollments_update_member on program_enrollments
  for update using (academy_id = current_academy_id())
  with check (academy_id = current_academy_id());

grant select, insert, update on programs, program_price_options, program_enrollments
  to authenticated;
revoke all on programs, program_price_options, program_enrollments from anon;

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0009_availability.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — private-lesson availability
--
-- Each coach sets the hours they offer private lessons on each weekday. This
-- only GUIDES booking (times outside it can still be booked deliberately,
-- exactly like a scheduling conflict); programs may run outside these hours.
--
-- Availability is per person, so a session needs to say who runs it:
-- sessions.coach_membership_id. It is what lets the app refuse to narrow
-- someone's availability underneath a lesson they already have booked.
-- ============================================================================

-- The signed-in user's own membership row.
create or replace function current_membership_id()
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select id from academy_memberships where auth_user_id = auth.uid();
$$;

revoke all on function current_membership_id() from public;
grant execute on function current_membership_id() to authenticated;

create table availability_windows (
  id             uuid primary key default gen_random_uuid(),
  academy_id     uuid not null references academies (id) on delete cascade,
  membership_id  uuid not null references academy_memberships (id) on delete cascade,
  -- 0 = Sunday … 6 = Saturday. A day with no row means "unavailable".
  weekday        smallint not null check (weekday between 0 and 6),
  start_min      integer not null check (start_min between 0 and 1439),
  end_min        integer not null check (end_min between 1 and 1440),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint availability_window_ordered check (end_min > start_min),
  constraint availability_one_per_day unique (membership_id, weekday)
);

create index availability_windows_academy_idx on availability_windows (academy_id);

create trigger availability_windows_updated_at before update on availability_windows
  for each row execute function set_updated_at();

-- A window must belong to a member of the same academy.
create or replace function guard_availability_same_academy()
returns trigger
language plpgsql
as $$
declare
  v_academy uuid;
begin
  select academy_id into v_academy from academy_memberships where id = new.membership_id;
  if v_academy is distinct from new.academy_id then
    raise exception 'Membership belongs to a different academy'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger availability_windows_same_academy
  before insert or update on availability_windows
  for each row execute function guard_availability_same_academy();

alter table availability_windows enable row level security;
alter table availability_windows force row level security;

-- Everyone in the academy can see when their teammates are available; you edit
-- only your own hours.
create policy availability_select_member on availability_windows
  for select using (academy_id = current_academy_id());

create policy availability_write_own on availability_windows
  for all using (
    academy_id = current_academy_id() and membership_id = current_membership_id()
  )
  with check (
    academy_id = current_academy_id() and membership_id = current_membership_id()
  );

grant select, insert, update, delete on availability_windows to authenticated;
revoke all on availability_windows from anon;

-- Who runs the session. NULL for sessions created before this existed.
alter table sessions
  add column coach_membership_id uuid references academy_memberships (id) on delete set null;

create index sessions_coach_membership_idx on sessions (coach_membership_id)
  where coach_membership_id is not null;

-- The runner must be in the same academy as the session.
create or replace function guard_same_academy()
returns trigger
language plpgsql
as $$
declare
  v_academy uuid;
begin
  if tg_table_name = 'enrollments' then
    select academy_id into v_academy from sessions where id = new.session_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Session belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;
    select academy_id into v_academy from players where id = new.player_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Player belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;

  elsif tg_table_name = 'charges' then
    select academy_id into v_academy from players where id = new.player_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Player belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;
    if new.session_id is not null then
      select academy_id into v_academy from sessions where id = new.session_id;
      if v_academy is distinct from new.academy_id then
        raise exception 'Session belongs to a different academy' using errcode = 'insufficient_privilege';
      end if;
    end if;
    if new.program_id is not null then
      select academy_id into v_academy from programs where id = new.program_id;
      if v_academy is distinct from new.academy_id then
        raise exception 'Program belongs to a different academy' using errcode = 'insufficient_privilege';
      end if;
    end if;

  elsif tg_table_name = 'program_enrollments' then
    select academy_id into v_academy from programs where id = new.program_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Program belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;
    select academy_id into v_academy from players where id = new.player_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Player belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;

  elsif tg_table_name = 'program_price_options' then
    select academy_id into v_academy from programs where id = new.program_id;
    if v_academy is distinct from new.academy_id then
      raise exception 'Program belongs to a different academy' using errcode = 'insufficient_privilege';
    end if;

  elsif tg_table_name = 'sessions' then
    if new.program_id is not null then
      select academy_id into v_academy from programs where id = new.program_id;
      if v_academy is distinct from new.academy_id then
        raise exception 'Program belongs to a different academy' using errcode = 'insufficient_privilege';
      end if;
    end if;
    if new.coach_membership_id is not null then
      select academy_id into v_academy from academy_memberships where id = new.coach_membership_id;
      if v_academy is distinct from new.academy_id then
        raise exception 'Coach belongs to a different academy' using errcode = 'insufficient_privilege';
      end if;
    end if;
  end if;

  return new;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0010_team.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — team: invitations, removal, and who worked a session
--
-- The owner invites a coach by email. There is no email service in this
-- application, so an invitation is a link the owner shares; the invited person
-- signs up with that email and is put in the inviter's academy AS A COACH
-- instead of getting an academy of their own. A membership's role is set only
-- at creation and never changed (0006), so nobody can be promoted through
-- this: invitations can only ever create coaches.
--
-- A person belongs to one academy (auth_user_id is unique on memberships), so
-- an existing CoachOS account cannot be invited into a second academy.
-- ============================================================================

-- ─────────────────────────────────────────────────────────── invitations ───

create table academy_invites (
  id           uuid primary key default gen_random_uuid(),
  academy_id   uuid not null references academies (id) on delete cascade,
  email        text not null check (email = lower(btrim(email)) and length(email) > 3),
  role         membership_role not null default 'coach' check (role = 'coach'),
  -- The shared secret in the invitation link.
  -- 64 hex characters from the core CSPRNG (no dependency on pgcrypto).
  token        text not null unique
    default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''),
  invited_by   uuid references academy_memberships (id) on delete set null,
  expires_at   timestamptz not null default now() + interval '14 days',
  accepted_at  timestamptz,
  revoked_at   timestamptz,
  created_at   timestamptz not null default now()
);

create index academy_invites_academy_idx on academy_invites (academy_id);
-- One open invitation per address per academy.
create unique index academy_invites_one_open
  on academy_invites (academy_id, email)
  where accepted_at is null and revoked_at is null;
-- Signup looks invitations up by email.
create index academy_invites_email_idx on academy_invites (email)
  where accepted_at is null and revoked_at is null;

alter table academy_invites enable row level security;
alter table academy_invites force row level security;

-- Invitations carry people's email addresses and a join secret: owner only.
create policy invites_select_owner on academy_invites
  for select using (academy_id = current_academy_id() and current_membership_role() = 'owner');
create policy invites_insert_owner on academy_invites
  for insert with check (academy_id = current_academy_id() and current_membership_role() = 'owner');
-- Revoking is an update (revoked_at); there is no delete.
create policy invites_update_owner on academy_invites
  for update using (academy_id = current_academy_id() and current_membership_role() = 'owner')
  with check (academy_id = current_academy_id() and current_membership_role() = 'owner');

-- Column-level privileges do the heavy lifting: an owner can create invitations
-- and revoke them, and can change NOTHING else about one. In particular
-- accepted_at can be written only by the SECURITY DEFINER signup functions
-- below, never by any client.
revoke all on academy_invites from anon, authenticated;
grant select, insert on academy_invites to authenticated;
grant update (revoked_at) on academy_invites to authenticated;

-- Defence in depth on top of the column privileges: an invitation's identity,
-- target and secret never change, and a revoked one stays revoked.
-- (`invited_by` is attribution and is nulled when that person is removed, so it
-- is deliberately not protected.)
create or replace function guard_invite_update()
returns trigger
language plpgsql
as $$
begin
  if new.academy_id is distinct from old.academy_id
     or new.email is distinct from old.email
     or new.role is distinct from old.role
     or new.token is distinct from old.token
     or new.expires_at is distinct from old.expires_at
     or new.created_at is distinct from old.created_at then
    raise exception 'An invitation cannot be edited; revoke it and send a new one'
      using errcode = 'insufficient_privilege';
  end if;
  -- A revoked invitation stays revoked.
  if old.revoked_at is not null and new.revoked_at is null then
    raise exception 'A revoked invitation cannot be reopened; send a new one'
      using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger academy_invites_update_guard
  before update on academy_invites
  for each row execute function guard_invite_update();

-- What the (signed-out) invitation page may show for a token: enough to say who
-- is inviting and which address to sign up with, and nothing else.
create or replace function get_invite_preview(p_token text)
returns table (business_name text, email text, state text)
language sql
stable
security definer
set search_path = public
as $$
  select
    a.business_name,
    i.email,
    case
      when i.accepted_at is not null then 'accepted'
      when i.revoked_at  is not null then 'revoked'
      when i.expires_at  <  now()    then 'expired'
      else 'open'
    end
  from academy_invites i
  join academies a on a.id = i.academy_id
  where i.token = p_token;
$$;

revoke all on function get_invite_preview(text) from public;
grant execute on function get_invite_preview(text) to anon, authenticated;

-- ────────────────────────────────────────── signup: join, or start a new one ─

-- An open, unexpired invitation for this address.
create or replace function open_invite_for(p_email text)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select id from academy_invites
   where email = lower(btrim(p_email))
     and accepted_at is null and revoked_at is null and expires_at > now()
   order by created_at
   limit 1;
$$;

revoke all on function open_invite_for(text) from public;

create or replace function handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_academy uuid;
  v_invite  academy_invites%rowtype;
  v_name    text := coalesce(new.raw_user_meta_data ->> 'name', '');
  v_email   text := coalesce(new.email, '');
begin
  if exists (select 1 from academy_memberships where auth_user_id = new.id) then
    return new;
  end if;

  select * into v_invite from academy_invites where id = open_invite_for(v_email);
  if found then
    insert into academy_memberships (academy_id, auth_user_id, role, name, email)
    values (v_invite.academy_id, new.id, 'coach', v_name, v_email);
    update academy_invites set accepted_at = now() where id = v_invite.id;
    return new;
  end if;

  insert into academies default values returning id into v_academy;
  insert into academy_memberships (academy_id, auth_user_id, role, name, email)
  values (v_academy, new.id, 'owner', v_name, v_email);
  return new;
end;
$$;

-- The application fallback for a signed-in user with no membership (see 0006).
-- It must honour an invitation too, or an invited person whose signup trigger
-- somehow didn't run would be stranded as the owner of an empty academy.
create or replace function bootstrap_academy_owner(p_name text, p_email text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_academy    uuid;
  v_membership uuid;
  v_invite     academy_invites%rowtype;
  v_email      text := coalesce(nullif(p_email, ''), (select email from auth.users where id = auth.uid()), '');
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = 'insufficient_privilege';
  end if;

  select id into v_membership from academy_memberships where auth_user_id = auth.uid();
  if found then
    return v_membership;
  end if;

  select * into v_invite from academy_invites where id = open_invite_for(v_email);
  if found then
    update academy_invites set accepted_at = now() where id = v_invite.id;
    insert into academy_memberships (academy_id, auth_user_id, role, name, email)
    values (v_invite.academy_id, auth.uid(), 'coach', coalesce(p_name, ''), v_email)
    returning id into v_membership;
    return v_membership;
  end if;

  insert into academies default values returning id into v_academy;
  insert into academy_memberships (academy_id, auth_user_id, role, name, email)
  values (v_academy, auth.uid(), 'owner', coalesce(p_name, ''), v_email)
  returning id into v_membership;
  return v_membership;
end;
$$;

-- ─────────────────────────────────────────────────────── removing a coach ──

-- The owner can remove a coach. Never an owner, never themself: an academy must
-- always have its owner.
create policy memberships_delete_owner on academy_memberships
  for delete using (
    academy_id = current_academy_id()
    and current_membership_role() = 'owner'
    and role = 'coach'
    and id <> current_membership_id()
  );

grant delete on academy_memberships to authenticated;

create or replace function guard_membership_delete()
returns trigger
language plpgsql
as $$
begin
  if old.role = 'owner' and current_membership_role() is not null then
    raise exception 'An academy''s owner cannot be removed'
      using errcode = 'insufficient_privilege';
  end if;
  return old;
end;
$$;

create trigger academy_memberships_delete_guard
  before delete on academy_memberships
  for each row execute function guard_membership_delete();

-- ──────────────────────────────────────────────── who worked a session ─────

create table session_coaches (
  session_id     uuid not null references sessions (id) on delete cascade,
  membership_id  uuid not null references academy_memberships (id) on delete cascade,
  academy_id     uuid not null references academies (id) on delete cascade,
  created_at     timestamptz not null default now(),
  primary key (session_id, membership_id)
);

create index session_coaches_academy_idx on session_coaches (academy_id);

create or replace function guard_session_coach_same_academy()
returns trigger
language plpgsql
as $$
declare
  v_academy uuid;
begin
  select academy_id into v_academy from sessions where id = new.session_id;
  if v_academy is distinct from new.academy_id then
    raise exception 'Session belongs to a different academy' using errcode = 'insufficient_privilege';
  end if;
  select academy_id into v_academy from academy_memberships where id = new.membership_id;
  if v_academy is distinct from new.academy_id then
    raise exception 'Coach belongs to a different academy' using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

create trigger session_coaches_same_academy
  before insert or update on session_coaches
  for each row execute function guard_session_coach_same_academy();

alter table session_coaches enable row level security;
alter table session_coaches force row level security;

-- Recording who was on court is part of taking attendance: any member.
create policy session_coaches_all_member on session_coaches
  for all using (academy_id = current_academy_id())
  with check (academy_id = current_academy_id());

grant select, insert, update, delete on session_coaches to authenticated;
revoke all on session_coaches from anon;

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0011_atomic_program_workflows.sql
-- ─────────────────────────────────────────────────────────────────────────
-- ============================================================================
-- CoachOS — atomic program workflows
--
-- Creating a program, and enrolling a participant, are each several writes. The
-- application talks to Postgres through PostgREST, which has no client-side
-- transaction, and nothing here can be undone by deleting (programs, roster
-- places and charges are history: no DELETE for anyone). So a failure part-way
-- through would leave a half-made program, or a roster place with no charge.
--
-- These two functions make each workflow ONE statement, and therefore one
-- transaction: everything commits, or nothing does.
--
-- They are deliberately SECURITY INVOKER. They run as the calling user, so row
-- level security and every guard trigger from 0006–0010 apply exactly as they
-- would to the individual inserts — only the owner can create a program or
-- agree a custom price; an agreement must match its price option; a program
-- charge must equal the participant's agreed price. The application still
-- decides WHAT to write (dates, agreement, charge period); these functions only
-- write it atomically.
-- ============================================================================

-- ─────────────────────────────────────────────────────────── create_program ─
--
--   p_program  {name, audience, weekdays[], start_min, duration_min, location,
--               capacity, age_range, starts_on, ends_on}
--   p_options  [{label, basis, amount_cents}, …]   (position = array order)
--   p_dates    the occurrence dates to schedule now
--
-- Returns the new program's id.

create or replace function create_program(p_program jsonb, p_options jsonb, p_dates date[])
returns uuid
language plpgsql
set search_path = public
as $$
declare
  v_academy  uuid := current_academy_id();
  v_program  uuid;
  v_option   jsonb;
  v_position integer := 0;
  v_date     date;
begin
  if v_academy is null then
    raise exception 'Not signed in to an academy' using errcode = 'insufficient_privilege';
  end if;
  if p_options is null or jsonb_typeof(p_options) <> 'array' or jsonb_array_length(p_options) = 0 then
    raise exception 'A program needs at least one price option' using errcode = 'check_violation';
  end if;

  insert into programs
    (academy_id, name, audience, weekdays, start_min, duration_min,
     location, capacity, age_range, starts_on, ends_on)
  values (
    v_academy,
    p_program ->> 'name',
    (p_program ->> 'audience')::program_audience,
    array(select v::smallint from jsonb_array_elements_text(p_program -> 'weekdays') as t(v)),
    (p_program ->> 'start_min')::integer,
    (p_program ->> 'duration_min')::integer,
    coalesce(p_program ->> 'location', ''),
    (p_program ->> 'capacity')::integer,
    coalesce(p_program ->> 'age_range', ''),
    (p_program ->> 'starts_on')::date,
    (p_program ->> 'ends_on')::date
  )
  returning id into v_program;

  for v_option in select * from jsonb_array_elements(p_options) loop
    insert into program_price_options (academy_id, program_id, label, basis, amount_cents, position)
    values (
      v_academy,
      v_program,
      v_option ->> 'label',
      (v_option ->> 'basis')::price_basis,
      (v_option ->> 'amount_cents')::integer,
      v_position
    );
    v_position := v_position + 1;
  end loop;

  -- A program's occurrences are unpriced group sessions: participants are
  -- charged from their agreements, not from the session.
  foreach v_date in array coalesce(p_dates, '{}'::date[]) loop
    insert into sessions
      (academy_id, type, name, date, start_min, duration_min, price_cents, is_free,
       location, capacity, program_id)
    values (
      v_academy,
      'group',
      p_program ->> 'name',
      v_date,
      (p_program ->> 'start_min')::integer,
      (p_program ->> 'duration_min')::integer,
      0,
      false,
      coalesce(p_program ->> 'location', ''),
      (p_program ->> 'capacity')::integer,
      v_program
    );
  end loop;

  return v_program;
end;
$$;

revoke all on function create_program(jsonb, jsonb, date[]) from public, anon;
grant execute on function create_program(jsonb, jsonb, date[]) to authenticated;

-- ───────────────────────────────────────────────────────── enroll_participant ─
--
--   p_enrollment  {program_id, player_id, joined_on, price_option_id, agreed_label,
--                  agreed_basis, agreed_amount_cents, standard_amount_cents,
--                  agreement_source, agreement_note}
--   p_session_ids the program's upcoming occurrences to put them on (expected)
--   p_charge      the first charge, or null when nothing is owed yet
--                 {amount_cents, price_source, price_basis, standard_amount_cents,
--                  period_start, period_end, due_date, label, note}
--
-- The roster place (with its agreement snapshot), the occurrences and the first
-- charge are written together. Returns {enrollment_id, charge_id}.

create or replace function enroll_participant(
  p_enrollment  jsonb,
  p_session_ids uuid[],
  p_charge      jsonb
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  v_academy uuid := current_academy_id();
  v_program uuid := (p_enrollment ->> 'program_id')::uuid;
  v_player  uuid := (p_enrollment ->> 'player_id')::uuid;
  v_enr     uuid;
  v_charge  uuid;
  v_session uuid;
begin
  if v_academy is null then
    raise exception 'Not signed in to an academy' using errcode = 'insufficient_privilege';
  end if;

  insert into program_enrollments
    (academy_id, program_id, player_id, joined_on, price_option_id, agreed_label,
     agreed_basis, agreed_amount_cents, standard_amount_cents, agreement_source,
     agreement_note)
  values (
    v_academy,
    v_program,
    v_player,
    (p_enrollment ->> 'joined_on')::date,
    (p_enrollment ->> 'price_option_id')::uuid,
    p_enrollment ->> 'agreed_label',
    (p_enrollment ->> 'agreed_basis')::price_basis,
    (p_enrollment ->> 'agreed_amount_cents')::integer,
    (p_enrollment ->> 'standard_amount_cents')::integer,
    (p_enrollment ->> 'agreement_source')::agreement_source,
    coalesce(p_enrollment ->> 'agreement_note', '')
  )
  returning id into v_enr;

  foreach v_session in array coalesce(p_session_ids, '{}'::uuid[]) loop
    if not exists (select 1 from sessions where id = v_session and program_id = v_program) then
      raise exception 'Session % is not part of this program', v_session
        using errcode = 'check_violation';
    end if;
    insert into enrollments (academy_id, session_id, player_id, expected)
    values (v_academy, v_session, v_player, true)
    on conflict (session_id, player_id) do nothing;
  end loop;

  if p_charge is not null and jsonb_typeof(p_charge) = 'object' then
    insert into charges
      (academy_id, player_id, session_id, program_id, program_enrollment_id,
       amount_cents, price_source, price_basis, standard_amount_cents,
       period_start, period_end, due_date, is_manual, label, note)
    values (
      v_academy,
      v_player,
      null,
      v_program,
      v_enr,
      (p_charge ->> 'amount_cents')::integer,
      (p_charge ->> 'price_source')::price_source,
      (p_charge ->> 'price_basis')::price_basis,
      (p_charge ->> 'standard_amount_cents')::integer,
      (p_charge ->> 'period_start')::date,
      (p_charge ->> 'period_end')::date,
      (p_charge ->> 'due_date')::date,
      false,
      coalesce(p_charge ->> 'label', ''),
      coalesce(p_charge ->> 'note', '')
    )
    returning id into v_charge;
  end if;

  return jsonb_build_object('enrollment_id', v_enr, 'charge_id', v_charge);
end;
$$;

revoke all on function enroll_participant(jsonb, uuid[], jsonb) from public, anon;
grant execute on function enroll_participant(jsonb, uuid[], jsonb) to authenticated;

